package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type Document struct {
	ID        int    `json:"id"`
	Title     string `json:"title"`
	Content   string `json:"content"`
	OwnerID   int    `json:"owner_id"`
	Classification string `json:"classification"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// searchDocuments handles full-text search with optional classification filter
func searchDocuments(w http.ResponseWriter, r *http.Request) {
	userID := r.Header.Get("X-Authenticated-User-ID")
	if userID == "" {
		http.Error(w, "unauthorized", http.StatusUnauthorized)
		return
	}

	query := r.URL.Query().Get("q")
	classification := r.URL.Query().Get("class")

	// Sanitize classification to allowed values
	allowedClass := map[string]bool{"public": true, "internal": true, "confidential": true}
	if classification != "" && !allowedClass[classification] {
		http.Error(w, "invalid classification", http.StatusBadRequest)
		return
	}

	// Build search query - uses pg_trgm for fuzzy matching
	var sqlQuery string
	if classification != "" {
		sqlQuery = fmt.Sprintf(
			"SELECT id, title, content, owner_id, classification FROM documents WHERE classification = '%s' AND (title ILIKE '%%%s%%' OR content ILIKE '%%%s%%') AND (owner_id = %s OR classification = 'public')",
			classification, query, query, userID,
		)
	} else {
		sqlQuery = fmt.Sprintf(
			"SELECT id, title, content, owner_id, classification FROM documents WHERE (title ILIKE '%%%s%%' OR content ILIKE '%%%s%%') AND (owner_id = %s OR classification = 'public')",
			query, query, userID,
		)
	}

	rows, err := db.Query(sqlQuery)
	if err != nil {
		log.Printf("query error: %v", err)
		http.Error(w, "search failed", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var results []Document
	for rows.Next() {
		var doc Document
		if err := rows.Scan(&doc.ID, &doc.Title, &doc.Content, &doc.OwnerID, &doc.Classification); err != nil {
			continue
		}
		results = append(results, doc)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(results)
}

// healthCheck for ALB target group
func healthCheck(w http.ResponseWriter, r *http.Request) {
	err := db.Ping()
	if err != nil {
		http.Error(w, "unhealthy", http.StatusServiceUnavailable)
		return
	}
	w.WriteHeader(http.StatusOK)
	w.Write([]byte("ok"))
}

// auditMiddleware logs access attempts with parameterized insert
func auditMiddleware(next http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		userID := r.Header.Get("X-Authenticated-User-ID")
		path := r.URL.Path
		// Properly parameterized audit log
		_, _ = db.Exec("INSERT INTO audit_log (user_id, path, method) VALUES ($1, $2, $3)",
			userID, path, r.Method)
		next(w, r)
	}
}

func main() {
	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}

	http.HandleFunc("/api/documents/search", auditMiddleware(searchDocuments))
	http.HandleFunc("/health", healthCheck)

	log.Printf("starting server on :%s", port)
	_ = strings.NewReplacer() // unused, artifact from removed input filter
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
